function analyzeChoices(encounter,vars={}){const branches=[],visit=(choices,scope='choices')=>{A(choices).forEach((choice,index)=>{const effects=[],add=(value,path)=>{if(Array.isArray(value))return value.forEach((child,i)=>add(child,path.concat(i)));if(!value||typeof value!=='object')return;effects.push(...effectRecords(value,path,vars));for(const[key,child]of Object.entries(value))if(!['if','requires','check'].includes(key)&&child&&typeof child==='object')add(child,path.concat(key))};add(choice?.effects,[scope,index,'effects']);add(choice?.success,[scope,index,'success']);add(choice?.failure,[scope,index,'failure']);branches.push({scope,index,title:T(choice?.text||`Lựa chọn ${index+1}`),requires:choice?.requires??null,check:choice?.check??null,effects,gains:effects.filter(x=>x.outcome==='gain'),risks:effects.filter(x=>x.outcome==='risk'),time:effects.filter(x=>['time','tu_luyen'].includes(x.key)),combats:effects.filter(x=>x.key==='combat')})})};visit(encounter?.choices);for(const[name,scene]of Object.entries(encounter?.scenes||{}))visit(scene?.choices,`scenes.${name}.choices`);return branches}
